  "avaliacoes": [
    {
      "id": "E11483a0c65448a26",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Os sistemas permanentes de amarração para estruturas flutuantes offshore incluem amarração em ponto único, ancoragem distribuída e posicionamento dinâmico, com diferenças de arquitetura e de modo de manutenção de posição.",
          "trechos": [
            "E11483a0c65448a26:0:695",
            "E11483a0c65448a26:695:1384"
          ],
          "condicoes": [
            "aplicado a estruturas flutuantes offshore como FPSO e FSO"
          ],
          "limites": [
            "o trecho apresenta classificação e descrição geral, sem critérios quantitativos de dimensionamento"
          ]
        },
        {
          "proposicao": "A ancoragem distribuída é descrita como utilizada em ambientes menos agressivos, com linhas distribuídas ao redor do navio para resistir aos carregamentos ambientais atuantes.",
          "trechos": [
            "E11483a0c65448a26:695:1384"
          ],
          "condicoes": [
            "ambientes considerados menos agressivos",
            "linhas distribuídas em torno do FPSO ou FSO"
          ],
          "limites": [
            "não define objetivamente o que caracteriza ambiente menos agressivo",
            "não informa limites de excursão nem critérios de aceitação"
          ]
        },
        {
          "proposicao": "A seleção da configuração das linhas de ancoragem considera tipo de plataforma, lâmina d’água, número de risers, intensidade das cargas e custo dos materiais; na configuração convencional em catenária há trecho apoiado no leito marinho, com transmissão apenas de esforços horizontais à fundação e maior raio de abrangência.",
          "trechos": [
            "E11483a0c65448a26:1384:2084",
            "E11483a0c65448a26:2084:2396"
          ],
          "condicoes": [
            "comparação entre configurações convencional, taut leg e tendões verticais",
            "na configuração convencional existe trecho da linha apoiado no leito marinho"
          ],
          "limites": [
            "o ângulo indicado no trecho está apagado",
            "o comprimento aproximado em função da lâmina d’água é apresentado como regra descritiva da configuração convencional, sem faixa de validade explicitada"
          ]
        }
      ]
    },
    {
      "id": "Ed9aeb2f7f95b1f29",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "As configurações CALM, SALM e turret são apresentadas como variantes de amarração em ponto único, enquanto DP e sistemas assistidos por impulsores atuam automaticamente para manter posição e aproamento desejados.",
          "trechos": [
            "Ed9aeb2f7f95b1f29:0:698"
          ],
          "condicoes": [
            "no caso do turret, a embarcação é conectada a uma estrutura cilíndrica ancorada ao fundo",
            "no caso de DP/TAS, há uso de impulsores convencionais, laterais ou azimutais"
          ],
          "limites": [
            "o trecho não compara desempenho entre alternativas nem trata de falha"
          ]
        },
        {
          "proposicao": "Entre os requisitos básicos de projeto para um campo definido estão carga proveniente de risers, descrição da bóia de conexão ou turret com tipos de risers, capacidade de armazenamento e sistema de ancoragem.",
          "trechos": [
            "Ed9aeb2f7f95b1f29:698:1395",
            "Ed9aeb2f7f95b1f29:1395:2094"
          ],
          "condicoes": [
            "o texto os apresenta como requisitos básicos de projeto baseados nas opções de aplicação do campo",
            "também considera agentes ambientais do local, peso da planta e área requerida"
          ],
          "limites": [
            "não prioriza nem hierarquiza os requisitos",
            "não fornece método de cálculo para resposta acoplada"
          ]
        },
        {
          "proposicao": "A seleção e o projeto de uma instalação FPSO são influenciados por fatores como localização e meio ambiente, função e vida útil do campo, layout e distribuição de pesos e dimensões.",
          "trechos": [
            "Ed9aeb2f7f95b1f29:1395:2094",
            "Ed9aeb2f7f95b1f29:2094:2238"
          ],
          "condicoes": [
            "o trecho atribui esses elementos a guidance notes do UKOOA"
          ],
          "limites": [
            "trata-se de referência a orientação estrangeira, não de requisito brasileiro",
            "a lista de dez elementos está incompleta no material fornecido"
          ]
        }
      ]
    },
    {
      "id": "E3b4c5c5ec2ab8244",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O sistema DICAS é descrito como permitindo saída de risers por todo o costado e, devido à diferença de rigidez entre linhas de proa e popa, oferecendo complacência angular da ordem de vinte graus, sendo indicado no texto para regiões em que o mar crítico predomina em uma direção.",
          "trechos": [
            "E3b4c5c5ec2ab8244:0:694"
          ],
          "condicoes": [
            "diferença de rigidez entre linhas de proa e popa",
            "predominância direcional do mar crítico"
          ],
          "limites": [
            "a indicação é contextual ao trecho, não uma regra universal de seleção",
            "não há comparação quantitativa completa com turret ou spread convencional"
          ]
        },
        {
          "proposicao": "A escolha entre linhas em catenária livre e Taut-Leg impacta deriva e raio de ancoragem; no sistema Taut-Leg as linhas ficam bem tracionadas, sem segmento apoiado no leito marinho, reduzindo o passeio do sistema, porém impondo cargas verticais à âncora.",
          "trechos": [
            "E3b4c5c5ec2ab8244:694:1393"
          ],
          "condicoes": [
            "comparação entre catenária livre e Taut-Leg"
          ],
          "limites": [
            "o trecho não quantifica redução de deriva nem magnitude das cargas verticais",
            "a comparação gráfica mencionada não está disponível aqui"
          ]
        },
        {
          "proposicao": "No caso estudado, a restrição de deriva máxima associada ao acoplamento do casco com a unidade cabeça de poço levou à escolha de SMS em Taut-Leg e impediu o uso de turret; além disso, a completação seca impõe baixo movimento vertical da unidade.",
          "trechos": [
            "E3b4c5c5ec2ab8244:694:1393",
            "E3b4c5c5ec2ab8244:1393:2038"
          ],
          "condicoes": [
            "casco acoplado com unidade cabeça de poço",
            "uso de completação seca"
          ],
          "limites": [
            "trata-se de seleção para o sistema estudado, não critério universal",
            "o valor numérico da deriva máxima permitida está apagado"
          ]
        }
      ]
    },
